#include <stdio.h>

int *chosen;

void choose(int *a, int *b) {
    if (*a >= *b) {
        chosen = a;
    } else {
        chosen = b;
    }
}

int main() {
    int p = 5, q = 9;
    choose(&p, &q);
    printf("%d\n", *chosen);
    return 0;
}

solution.code:
#include <stdio.h>

int *larger(int *a, int *b) {
    return *a >= *b ? a : b;
}

int main() {
    int p = 5, q = 9;
    printf("%d\n", *larger(&p, &q));
    return 0;
}
